INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(32361, 'Job 20:10', 'Job', 20, 10, 'د هغوئ د اولاد نه به هغه مال دولت واپس لاړ شى، چې کوم يې د غريبانانو نه اخستے وى.', 'د هغوی د اولاد نه به هغه مال دولت واپس لار شی، چې کوم یې د غریبانانو نه اخستے وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(32362, 'Job 20:11', 'Job', 20, 11, 'هغوئ به په ځوانۍ کښې مړۀ شى او په خاورو کښې به ښخ شى.', 'هغوی به په جوانی کشې مرۀ شی او په خاورو کشې به شخ شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32363, 'Job 20:12', 'Job', 20, 12, 'په بدعملۍ کښې خوند وى، او د دې خوند تر ډېر وخته پورې وى.', 'په بدعملی کشې خوند وی، او د دې خوند تر دېر وخته پورې وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(32364, 'Job 20:13', 'Job', 20, 13, 'او د خوږ څيز په شان يې په خولۀ کښې د ډېر وخت پورې ساتى،', 'او د خوز چیز په شان یې په خولۀ کشې د دېر وخت پورې ساتی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32365, 'Job 20:14', 'Job', 20, 14, 'خو ناګهانه د هغوئ خوراک په خېټه کښې تريخ شى، او د دې نه دننه زهر جوړ شى.', 'خو ناګهانه د هغوی خوراک په خېته کشې تریخ شی، او د دې نه دننه زهر جور شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32366, 'Job 20:15', 'Job', 20, 15, 'هغوئ مال دولت تېر کړى خو بيا يې اولټۍ کړى، خُدائ پاک د هغوئ دولت د هغوئ د خېټې نه واپس راوغورزوى.', 'هغوی مال دولت تېر کری خو بیا یې اولتی کری، خدای پاک د هغوی دولت د هغوی د خېتې نه واپس راوغورزوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(32367, 'Job 20:16', 'Job', 20, 16, 'هغوئ به د مارانو زهر وخورى، او زهرژن مار به هغوئ ووژنى.', 'هغوی به د مارانو زهر وخوری، او زهرژن مار به هغوی ووژنی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32368, 'Job 20:17', 'Job', 20, 17, 'هغوئ به سيندونه ونۀ ګورى، هغه نِهرونه چې شات او پئ په کښې بهيږى.', 'هغوی به سیندونه ونۀ ګوری، هغه نهرونه چې شات او پی په کشې بهیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32369, 'Job 20:18', 'Job', 20, 18, 'د هغوئ ناجائزه ګټه به د هغوئ نه واپس وځى، او په مال دولت باندې به خوشحالى ونۀ کړى،', 'د هغوی ناجایزه ګته به د هغوی نه واپس وجی، او په مال دولت باندې به خوشحالی ونۀ کری،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32370, 'Job 20:19', 'Job', 20, 19, 'ځکه چې هغوئ غريبانان وهلى دى او نهر يې پرېښى دى، او د هغوئ کورونه يې قبضه کړى دى کوم چې هغوئ نۀ دى جوړ کړى.', 'جکه چې هغوی غریبانان وهلی دی او نهر یې پرېشی دی، او د هغوی کورونه یې قبضه کری دی کوم چې هغوی نۀ دی جور کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_19.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(32371, 'Job 20:20', 'Job', 20, 20, 'د هغوئ د حرص ختمېدل نشته، چې په څۀ خوشحاليږى نو د هغې نه به ورسره هيڅ پاتې نۀ شى.', 'د هغوی د حرص ختمېدل نشته، چې په چۀ خوشحالیزی نو د هغې نه به ورسره هیچ پاتې نۀ شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32372, 'Job 20:21', 'Job', 20, 21, 'هغوئ چې څۀ خورى نو د هغې نه هيڅ نۀ پاتې کيږى، نو په دې وجه د هغوئ مالدارى ختميږى.', 'هغوی چې چۀ خوری نو د هغې نه هیچ نۀ پاتې کیزی، نو په دې وجه د هغوی مالداری ختمیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32373, 'Job 20:22', 'Job', 20, 22, 'کله چې هغوئ ښۀ کامياب وى، نو د غم چپې به په هغوئ باندې راشى.', 'کله چې هغوی شۀ کامیاب وی، نو د غم چپې به په هغوی باندې راشی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32374, 'Job 20:23', 'Job', 20, 23, 'چې کله هغوئ خپلې خېټې ډکې کړى نو خُدائ پاک دې په هغوئ باندې سخت قهر راولى، او دا قهر دې په هغوئ لکه د ږلۍ راوريږى.', 'چې کله هغوی خپلې خېتې دکې کری نو خدای پاک دې په هغوی باندې سخت قهر راولی، او دا قهر دې په هغوی لکه د زلی راوریزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32375, 'Job 20:24', 'Job', 20, 24, 'هغوئ به د اوسپنې د وسلې نه تښتى، خو د زېړو په غشى به هغوئ ولګى.', 'هغوی به د اوسپنې د وسلې نه تشتی، خو د زېرو په غشی به هغوی ولګی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32376, 'Job 20:25', 'Job', 20, 25, 'هغه غشے د هغوئ د ملا نه وويستلے شى، او دا غشے په وينه سور وى، يره به په هغوئ باندې راشى.', 'هغه غشے د هغوی د ملا نه وویستلے شی، او دا غشے په وینه سور وی، یره به په هغوی باندې راشی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32377, 'Job 20:26', 'Job', 20, 26, 'د هغوئ خزانه به په تکه توره تيارۀ کښې پټه شى، يو داسې اور به هغوئ تباه کړى چې هيچا بل کړے نۀ وى، او د هغوئ په کور کښې پاتې هر څۀ به تباه شى.', 'د هغوی خزانه به په تکه توره تیارۀ کشې پته شی، یو داسې اور به هغوی تباه کری چې هیچا بل کرے نۀ وی، او د هغوی په کور کشې پاتې هر چۀ به تباه شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32378, 'Job 20:27', 'Job', 20, 27, 'آسمانونه به د هغوئ ګناه ښکاره کړى، او زمکه به د هغوئ خِلاف ګواهى ورکوى.', 'اسمانونه به د هغوی ګناه شکاره کری، او زمکه به د هغوی خلاف ګواهی ورکوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_27.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(32379, 'Job 20:28', 'Job', 20, 28, 'يو سېلاب به د هغۀ کور يوسى، د خُدائ پاک قهر به په هغوئ سېلاب راولى.', 'یو سېلاب به د هغۀ کور یوسی، د خدای پاک قهر به په هغوی سېلاب راولی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32380, 'Job 20:29', 'Job', 20, 29, 'دا د خُدائ پاک د طرف نه د بدعمله کسانو اَنجام دے، دا د هغوئ هغه ميراث دے چې د خُدائ پاک د طرف نه يې فېصله شوې ده.“', 'دا د خدای پاک د طرف نه د بدعمله کسانو انجام دے، دا د هغوی هغه میراث دے چې د خدای پاک د طرف نه یې فېصله شوې ده.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_20_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32381, 'Isaiah 45:1', 'Isaiah', 45, 1, 'څښتن ټاکلی دی کوروش چې شي پاچا او زور او واک یې دی ورکړی ورته چې قومونه یې تابع شي چې کړي لېرې پاچاهان له واکه څښتن به خلاصې دروازې کړي د ښار د هغه دپاره او نورې به نه بندیږي څښتن کوروش ته داسې وایي:', 'چشتن تاکلی دی کوروش چې شی پاچا او زور او واک یې دی ورکری ورته چې قومونه یې تابع شی چې کری لېرې پاچاهان له واکه چشتن به خلاصې دروازې کری د شار د هغه دپاره او نورې به نه بندیزی چشتن کوروش ته داسې وایی:', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah045_verse_001.mp3', 'https://drive.google.com/file/d/1zTerQ9iJAz0p7NB0OLB6u0kHDw88Duyw/preview', 1761237836, 1761237836),
(32382, 'Isaiah 45:2', 'Isaiah', 45, 2, '«زه به په خپله ځمه ستا نه مخکې او هوار به کړمه غرونه زه به برنجي دروازې ماتې کړمه او اړمونه به یې د اوسپنې ټوټې ټوټې کړم', '«زه به په خپله جمه ستا نه مخکې او هوار به کرمه غرونه زه به برنجی دروازې ماتې کرمه او ارمونه به یې د اوسپنې توتې توتې کرم', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah045_verse_002.mp3', 'https://drive.google.com/file/d/1Afqpq27WQXllRFAtfSFTK4xuxXsJXlCX/preview', 1761237836, 1761237836),
(32383, 'Isaiah 45:3', 'Isaiah', 45, 3, 'زه به تاته خزانې درکړم د تورو تیارو ځایونو او هم به درکړم شتمني تاته د پټو ځایونو بیا به ته پوه شې چې زه څښتن د اسراییلو خدای یم څوک چې تاته کړي په نوم اواز', 'زه به تاته خزانې درکرم د تورو تیارو جایونو او هم به درکرم شتمنی تاته د پتو جایونو بیا به ته پوه شې چې زه چشتن د اسراییلو خدای یم چوک چې تاته کری په نوم اواز', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah045_verse_003.mp3', 'https://drive.google.com/uc?id=1MxO-k7sWcO-bGZgmsF1rLkFwPJor92zC&export=download', 1761237836, 1761237836),
(32384, 'Isaiah 45:4', 'Isaiah', 45, 4, 'ته مې ټاکلی یې ترڅو مرسته وکړې زما د خدمتګار یعقوب او مرسته وکړې زما د غوره شوي قوم اسراییلو سره سره له دې چې ته ما نه پېژنې زه په نوم اواز کومه تاته او درکوم لقب د عزت تاته', 'ته مې تاکلی یې ترچو مرسته وکرې زما د خدمتګار یعقوب او مرسته وکرې زما د غوره شوی قوم اسراییلو سره سره له دې چې ته ما نه پېژنې زه په نوم اواز کومه تاته او درکوم لقب د عزت تاته', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah045_verse_004.mp3', 'https://drive.google.com/file/d/1HPrdqRtTJURcpyY2Oo-z8LUG5bplt-vV/preview', 1761237836, 1761237836),
(32385, 'Isaiah 45:5', 'Isaiah', 45, 5, 'زه څښتن یم، نشته بل خدای پرته له ما سره له دې چې ته ما نه پېژنې زه به تاته درکړم توان', 'زه چشتن یم، نشته بل خدای پرته له ما سره له دې چې ته ما نه پېژنې زه به تاته درکرم توان', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah045_verse_005.mp3', 'https://drive.google.com/file/d/1k-oChrpujGn888UTNq4yXFhmOBiLbMS7/preview', 1761237836, 1761237836),
(32386, 'Isaiah 45:6', 'Isaiah', 45, 6, 'د دې دپاره زه کوم دا کار چې له ختیځه تر لوېدیځه پورې ټول خلک پوه شي په دې چې زه څښتن یم او بل خدای نشته', 'د دې دپاره زه کوم دا کار چې له ختیجه تر لوېدیجه پورې تول خلک پوه شی په دې چې زه چشتن یم او بل خدای نشته', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah045_verse_006.mp3', 'https://drive.google.com/file/d/18AexldbykdIvLPcg3fsfF7OeBD0sghJM/preview', 1761237836, 1761237836),
(32387, 'Isaiah 45:7', 'Isaiah', 45, 7, 'زه خالق یم د تیارې او رڼا زه راولمه مصیبت او سوله زه څښتن یم او کوم دا ټول کارونه', 'زه خالق یم د تیارې او رنا زه راولمه مصیبت او سوله زه چشتن یم او کوم دا تول کارونه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah045_verse_007.mp3', 'https://drive.google.com/file/d/1Qlt3JYxNLqtXa7GorsA3vWks_Ax9mUIl/preview', 1761237836, 1761237836),
(32388, 'Isaiah 45:8', 'Isaiah', 45, 8, 'ای اسمانه، ای ورېځو راووروه ته عدالت لکه باران په شان ځمکه دې پرانیستل شي ترڅو خلاصون او عدالت راشين شي او په کې وغوړیږي د عدالت او د خلاصون غوټۍ زه څښتن کوم دا ټول کارونه»', 'ای اسمانه، ای ورېجو راووروه ته عدالت لکه باران په شان جمکه دې پرانیستل شی ترچو خلاصون او عدالت راشین شی او په کې وغوریزی د عدالت او د خلاصون غوتی زه چشتن کوم دا تول کارونه»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah045_verse_008.mp3', 'https://drive.google.com/uc?id=12JMTldmbTaQXBqlwXkMf9oWZJuFqRU71&export=download', 1761237836, 1761237836),
